import{S as t,o as a,c as s,a9 as i,B as n}from"./chunks/framework.DxG24V0C.js";const p="/agentsrc/images/codex/08-app-server-architecture.svg",c="/agentsrc/images/codex/08-reverse-approval.svg",S=JSON.parse('{"title":"Codex 后台服务：它是如何为外部生态提供底层引擎的？","description":"","frontmatter":{"title":"Codex 后台服务：它是如何为外部生态提供底层引擎的？"},"headers":[],"relativePath":"codex/08-app-server.md","filePath":"codex/08-app-server.md","lastUpdated":1788847143000}'),l={name:"codex/08-app-server.md"},g=Object.assign(l,{setup(d){const o=[{question:"相比于将所有的 Agent 逻辑直接写在特定 IDE 插件的 Node.js 运行时中，Codex 采用独立 App Server 架构的核心优势是什么？",options:["极大降低了代码的编写难度，因为 Rust 语言自带了丰富的 UI 组件库用于前端渲染","彻底解决了大模型幻觉问题，后台运行的进程能够自动识别并过滤掉所有带有逻辑错误的代码修改","实现了状态管理与 UI 渲染的解耦，突破了单端生态限制，并便于利用底层操作系统的沙箱与多线程控制","绕过了 LLM 厂商的 API 速率限制，独立的进程能够并发发送海量 HTTP 请求而不被封禁"],correct:2,explanation:"纯插件架构会受限于特定 IDE 的生态，且沙箱权限和状态管理受限。剥离为 App Server 解决了跨平台复用、底层权限获取和核心任务稳定性的问题。"},{question:"在 codex app-server 支持的传输层中，默认且最轻量的通信方式 stdio:// 适合哪种运行场景？",options:["适合跨越多台服务器的分布式集群通信，通过长连接保持高吞吐量","适合作为 Local Daemon 在后台持久运行，即使所有客户端断开也会永远保持存活","适合被外部客户端（如 IDE 插件）作为子进程拉起，通过 stdin/stdout 进行 JSONL 通信，且默认随连接关闭而退出","适合绕过企业级防火墙的安全检查，因为它自动对标准输入输出进行了端到端加密"],correct:2,explanation:"stdio:// 最轻量，适合单客户端模式。IDE 插件拉起它并通过 stdin/stdout 通信，但在默认 single client mode 下，连接断开后服务端也会退出。"},{question:"Codex 的 App Server 采用的轻量 JSON-RPC 风格协议，在通信方向上包含哪三种关键类型？",options:["HTTP GET 获取资源、HTTP POST 提交任务、HTTP DELETE 删除会话","ClientRequest（客户端请求）、ServerNotification（服务端广播通知）、ServerRequest（服务端要求客户端响应，如审批）","Synchronous Call（同步阻塞调用）、Asynchronous Promise（异步回调）、Fire-and-forget（发后即忘指令）","GraphQL Query（图查询）、GraphQL Mutation（图变更）、GraphQL Subscription（图状态订阅）"],correct:1,explanation:"协议设计支持双向流：前端主动发起 Request，后端单向推送 Notification（如流式输出），以及后端主动发起反向 Request 要求前端审批（如 fileChange/requestApproval）。"},{question:"在 App Server 的内部架构中，当接收到一个 turn/start 的外部 JSON 请求时，它的处理链路是怎样的？",options:["由 MessageProcessor 转换后直接越过所有安全检查，强行修改底层数据库中的对话历史记录","由 TurnRequestProcessor 拦截并暂存在内存中，等待下一次 run_auto_compact 执行时批量提交给模型","被反序列化后交给 TurnRequestProcessor，并根据串行化控制规则，转换为内部的 Op::UserInput 投递给底层线程","被原封不动地转发给外部的 MCP 服务器，由第三方扩展负责处理该回合的生成逻辑"],correct:2,explanation:"App Server 是状态维持者。MessageProcessor 解析出 ClientRequest 后，分发给特定 Processor（受 serialization 串行化约束），再翻译为核心引擎认识的 Op 消息。"},{question:"当 Codex 底层执行发现需要人工审批一个 Shell 命令时，App Server 是如何实现与外部互动的？",options:['直接强制阻塞终端的标准输出流（stdout），要求用户在命令行中输入 "yes" 后才恢复执行',"向客户端发送 item/commandExecution/requestApproval 的反向请求，挂起底层任务，等待客户端收集用户决策并返回结果","通过操作系统的 notify-send 或 macOS 通知中心弹窗警告用户，但默认在 5 秒后自动放行命令","生成一个临时的 HTML 审批网页，并尝试自动打开用户电脑的默认浏览器要求点击确认"],correct:1,explanation:"这是典型的“服务端请求客户端”场景。引擎挂起任务，App Server 发送对应的审批方法请求给 IDE，IDE 收集决策后回传，App Server 解析后投递内部指令唤醒底层任务。"}];return(u,e)=>{const r=t("Quiz");return a(),s("div",null,[e[0]||(e[0]=i("",42)),n(r,{questions:o})])}}});export{S as __pageData,g as default};
